import{_ as l,l as r,o as e,c as h,v as t,p as n,x as i,d as s,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"掩模阴影","description":"","frontmatter":{"title":"掩模阴影","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mask-shadowing.md","filePath":"litho/mask-shadowing.md","lastUpdated":1789023840000}'),d={name:"litho/mask-shadowing.md"};function c(m,a,D,V,u,_){const o=r("Mermaid");return e(),h("div",null,[a[1]||(a[1]=t('<h1 id="掩模阴影" tabindex="-1">掩模阴影 <a class="header-anchor" href="#掩模阴影" aria-label="Permalink to &quot;掩模阴影&quot;">​</a></h1><div class="epigraph"><p>吸收体有高度，主光线不垂直：迎光侧多挡一截，有效开口变窄并像在物面平移。这是几何阴影，不是工件台套刻。</p><footer>—— 据 DUV 离轴与 EUV 反射掩模 3D 的公开讨论（Mack / Levinson 的 thick-mask 语境，以及 ASML 等对 EUV 吸收体阴影的表述）</footer></div><p><a href="/litho/kirchhoff-vs-emf">上一课</a>比较了薄屏与严格电磁：级振幅何时必须解麦克斯韦。缺口是斜入射下最显眼的那一项几何——厚吸收体投下的阴影。HV 偏置与「假套刻」位移要从阴影图画清楚，再把残差交给求解器。掩模 CD 与放置误差如何进晶圆，留给<a href="/litho/mask-cd-ppe">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课的 EMF 库会自动含阴影，但产线语言仍要把阴影单独钉死：否则计量上看到的左右 CD 差、沿扫描狭缝的 CD 指纹，会被写成 overlay 或剂量。DUV 上，<a href="/litho/off-axis-illumination">离轴照明</a>让掩模侧主光线已有角度；EUV 上，反射式照明典型约 \\(6^\\circ\\) 入射，吸收体再走一截高度，阴影更重。</p><p>缺口因此是「厚度 × 斜入射」的几何，而不是再论证 Kirchhoff 失败。没有这张图，下一课的 PPE 会和阴影位移缠成一个纳米数。</p><h3 id="阴影不是-overlay" tabindex="-1">阴影不是 overlay <a class="header-anchor" href="#阴影不是-overlay" aria-label="Permalink to &quot;阴影不是 overlay&quot;">​</a></h3><p>图形沿投影方向看起来平移并变窄，像套刻，根子在物面有效孔径。它随狭缝位置（主光线角）变，全场指纹与工件台编码器无关。补偿在吸收体偏置、OPC 的 M3D、有时在掩模台小倾角策略里，不在套刻标记读数里消去。上一课已警告过这一点；本课把它画成入射–高度三角形。</p><p><span class="marginnote">EUV 公开讨论里的约 \\(6^\\circ\\) 是照明几何量级，不是每台每场的精密常数。狭缝两端角度再变，阴影指纹沿场变化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>几何一阶：有效宽度约减 \\(h\\tan\\theta\\) 量级（\\(\\theta\\) 为掩模侧入射角，\\(h\\) 为吸收体高度），方位决定哪条边是迎光侧。DUV 透射：离轴极让左右边不对称。EUV 反射：光束进、出各经过吸收体附近一次，阴影与多层膜衍射叠在一起，不能只用透射铬的直觉。减薄吸收体、换低 \\(n\\)/\\(k\\) 材料是硬件方向，检测与光学密度另账，本课不选膜。</p><p>OPC：按方位与狭缝位置给不同偏置，而不是全局加一个 CD。照明一换（更离轴），\\(\\theta\\) 变，阴影表要重做。</p><h3 id="duv-与-euv-不要共用一张表" tabindex="-1">DUV 与 EUV 不要共用一张表 <a class="header-anchor" href="#duv-与-euv-不要共用一张表" aria-label="Permalink to &quot;DUV 与 EUV 不要共用一张表&quot;">​</a></h3><p>浸没 DUV 的掩模侧角通常小于 EUV 的 6° 量级，但 MoSi 厚度仍够在强偶极下做出可测 HV。EUV 几乎总要把阴影当一阶。High-NA EUV 掩模侧角度更大、半场扫描，阴影按方位更重，那是 EXE 附件；本课只钉机制。</p>',14)),(e(),n(p,null,{default:i(()=>[E(o,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20TH%5B%22%E5%90%B8%E6%94%B6%E4%BD%93%E9%AB%98%E5%BA%A6%20h%22%5D%20--%3E%20SH%5B%22%E9%98%B4%E5%BD%B1%20h%20tan%20%CE%B8%22%5D%0A%20%20ANG%5B%22%E6%96%9C%E5%85%A5%E5%B0%84%20%CE%B8%22%5D%20--%3E%20SH%0A%20%20SH%20--%3E%20CD%5B%22%E6%9C%89%E6%95%88%20CD%20%E5%8F%98%E7%AA%84%22%5D%0A%20%20SH%20--%3E%20SHIFT%5B%22%E8%A1%A8%E8%A7%82%E7%89%A9%E9%9D%A2%E5%B9%B3%E7%A7%BB%22%5D%0A%20%20SH%20--%3E%20NOTOV%5B%22%E4%B8%8D%E6%98%AF%E5%B7%A5%E4%BB%B6%E5%8F%B0%20overlay%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>迎光壁挡住一部分入射（EUV 上还挡反射回程），背光壁少挡，等效孔径既窄又偏。严格电磁会修正边缘场，所以「\\(h\\tan\\theta\\)」只是点名机制，OPC 仍用上一课的级库而不是纯几何。通过焦点时，阴影与波导相位一起让左右边的最佳焦距分裂，E–D 窗口在焦轴上再被切一刀。</p><p>扫描狭缝里主光线角连续变，同一设计条在场左右 CD 不同。这与透镜畸变、扫描同步是不同源，拆指纹时要分开。SRAF 更窄，相对高度更大，阴影可让杆的一侧「更不印」、另一侧接近印出。</p><p>上一课的求解器切换在这里变成：纯几何 \\(h\\tan\\theta\\) 用来点名和做 sanity check；签字仍用电磁级振幅，因为边缘场会改「有效 \\(h\\)」。只拿三角形去 OPC，曲边和细杆会系统残。</p><p><span class="marginnote">把阴影位移喂进套刻校正，会把物面系统误差写进工件台，换层或换照明后残差爆。计量上阴影走 CD / 不对称，overlay 走标记。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把掩模 CD 均匀性、写场对准、图案放置误差算进阴影——那些是掩模厂误差源，下一课经 MEF 进晶圆。也不把 pellicle 皱纹、多层膜缺陷叫成阴影。LELE 两次曝光各带自己的阴影指纹，叠加规则在多重图形课，这里不染色。</p><p>不要编吸收体纳米厚度或某节点良率。公开表述停在：EUV 斜入射 + 厚吸收体 ⇒ 阴影一阶；DUV 离轴同样机制、通常更弱。</p><p><span class="marginnote">表观平移随 \\(\\theta\\) 变，故随极方位变。偶极层的阴影方向与 C-quad 层不同，OPC 偏置不能共用。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>厚吸收体加斜入射产生几何阴影：有效 CD 变窄并表观平移。</li><li>不是套刻；随狭缝角与照明方位变。</li><li>DUV 离轴与 EUV 反射都有，EUV 通常更重。</li><li>一阶可用 \\(h\\tan\\theta\\) 点名，定量仍走 EMF 级库。</li><li>掩模 CD / PPE 下一课。</li><li>出处：thick-mask / EUV mask 3D 公开讨论（Mack、Levinson；ASML 等对 EUV 吸收体阴影）。</li></ul>',11))])}const B=l(d,[["render",c]]);export{A as __pageData,B as default};
